// Applied rules: [III②, III④, C3]
// Skipped rules: [C3.S1: Would require changing `counts: *mut size_t` to a reference/slice and therefore cross-function caller proof for a public function; body-local III④ + C3.S2 captures most of the payoff without signature churn.]
#[inline]
pub unsafe fn OptimizeHuffmanForRle(
    mut length: c_int,
    mut counts: *mut size_t,
) {
    let mut i: c_int = 0;
    let mut k: c_int = 0;
    let mut stride: c_int = 0;
    let mut symbol: size_t = 0;
    let mut sum: size_t = 0;
    let mut limit: size_t = 0;

    while length >= 0 as c_int {
        if length == 0 as c_int {
            return;
        }
        // SAFETY: caller provides `counts` for at least the original `length` elements;
        // this access uses index `length - 1`, which is in-bounds while `length > 0`.
        let tail = unsafe { *counts.offset((length - 1 as c_int) as isize) };
        if tail != 0 as size_t {
            break;
        }
        length -= 1;
    }

    // SAFETY: after trimming, all later accesses to `counts` are guarded to only
    // dereference indices in `0..length`. Caller guarantees `counts` points to a
    // writable buffer of at least that many `size_t` elements, and no Rust references
    // alias this memory for the duration of this function.
    let counts = unsafe { core::slice::from_raw_parts_mut(counts, length as usize) };
    let mut good_for_rle = vec![0 as c_int; length as usize];

    symbol = counts[0];
    stride = 0 as c_int;
    i = 0 as c_int;
    while i < length + 1 as c_int {
        let count_i = if i != length {
            counts[i as usize]
        } else {
            0 as size_t
        };
        if i == length || count_i != symbol {
            if symbol == 0 as size_t && stride >= 5 as c_int
                || symbol != 0 as size_t && stride >= 7 as c_int
            {
                k = 0 as c_int;
                while k < stride {
                    good_for_rle[(i - k - 1 as c_int) as usize] = 1 as c_int;
                    k += 1;
                }
            }
            stride = 1 as c_int;
            if i != length {
                symbol = count_i;
            }
        } else {
            stride += 1;
        }
        i += 1;
    }

    stride = 0 as c_int;
    limit = counts[0];
    sum = 0 as size_t;
    i = 0 as c_int;
    while i < length + 1 as c_int {
        let good_i = if i != length {
            good_for_rle[i as usize]
        } else {
            0 as c_int
        };
        let count_i = if i != length {
            counts[i as usize]
        } else {
            0 as size_t
        };
        if i == length || good_i != 0 || AbsDiff(count_i, limit) >= 4 as size_t {
            if stride >= 4 as c_int
                || stride >= 3 as c_int && sum == 0 as size_t
            {
                let mut count: c_int =
                    sum.wrapping_add((stride / 2 as c_int) as size_t)
                        .wrapping_div(stride as size_t) as c_int;
                if count < 1 as c_int {
                    count = 1 as c_int;
                }
                if sum == 0 as size_t {
                    count = 0 as c_int;
                }
                k = 0 as c_int;
                while k < stride {
                    counts[(i - k - 1 as c_int) as usize] = count as size_t;
                    k += 1;
                }
            }
            stride = 0 as c_int;
            sum = 0 as size_t;
            if i < length - 3 as c_int {
                let base = i as usize;
                let c0 = counts[base];
                let c1 = counts[base + 1];
                let c2 = counts[base + 2];
                let c3 = counts[base + 3];
                limit = c0
                    .wrapping_add(c1)
                    .wrapping_add(c2)
                    .wrapping_add(c3)
                    .wrapping_add(2 as size_t)
                    .wrapping_div(4 as size_t);
            } else if i < length {
                limit = count_i;
            } else {
                limit = 0 as size_t;
            }
        }
        stride += 1;
        if i != length {
            sum = sum.wrapping_add(count_i);
        }
        i += 1;
    }
}

